-- PostgreSQL reference schema for production persistence.
create extension if not exists pgcrypto;

create table if not exists organizations(id uuid primary key default gen_random_uuid(),name text not null,created_at timestamptz not null default now());
create table if not exists users(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,email text not null unique,display_name text,created_at timestamptz not null default now());
create table if not exists email_accounts(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,user_id uuid not null references users(id) on delete cascade,provider text not null check(provider in ('gmail')),provider_account_id text not null,encrypted_refresh_token text not null,scopes text[] not null default '{}',created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(provider,provider_account_id));
create table if not exists permission_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,user_id uuid not null references users(id) on delete cascade,action text not null,mode text not null check(mode in ('ask','auto','deny')),min_confidence numeric(4,3),allowed_categories text[] not null default '{}',blocked_categories text[] not null default '{}',allowed_senders text[] not null default '{}',blocked_senders text[] not null default '{}',max_bulk_size integer,created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists organization_policies(organization_id uuid primary key references organizations(id) on delete cascade,blocked_actions text[] not null default '{}',blocked_categories text[] not null default '{}',require_approval_for text[] not null default '{}',updated_at timestamptz not null default now());
create table if not exists automation_rules(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,user_id uuid not null references users(id) on delete cascade,name text not null,enabled boolean not null default true,conditions jsonb not null default '{}',actions jsonb not null default '[]',permission_mode text not null check(permission_mode in ('ask','auto','deny')),created_at timestamptz not null default now(),updated_at timestamptz not null default now());
create table if not exists approval_requests(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,user_id uuid not null references users(id) on delete cascade,proposal jsonb not null,risk text not null,status text not null check(status in ('pending','approved','rejected','expired')),created_at timestamptz not null,expires_at timestamptz not null,decided_at timestamptz,decided_by uuid references users(id));
create table if not exists audit_events(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,user_id uuid not null references users(id),account_id uuid references email_accounts(id),email_id text,thread_id text,action text not null,outcome text not null,risk text not null,reason text not null,confidence numeric(4,3),metadata jsonb,occurred_at timestamptz not null default now());
create table if not exists idempotency_keys(key text primary key,created_at timestamptz not null default now(),expires_at timestamptz not null);
create table if not exists threads(id uuid primary key default gen_random_uuid(),organization_id uuid not null references organizations(id) on delete cascade,subject text,root_message_id uuid references email_accounts(id),created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(organization_id,root_message_id));
create table if not exists messages(id uuid primary key default gen_random_uuid(),thread_id uuid not null references threads(id) on delete cascade,organization_id uuid not null references organizations(id) on delete cascade,user_id uuid not null references users(id) on delete cascade,email_account_id uuid references email_accounts(id),message_id text not null,references_message_id uuid,subject text,body text,direction text not null check(direction in ('inbound','outbound')),status text not null check(status in ('new','read','archived','deleted')),received_at timestamptz,sent_at timestamptz,opened_at timestamptz, flags text[] not null default '{}',headers jsonb,created_at timestamptz not null default now(),updated_at timestamptz not null default now(),unique(thread_id,message_id));

create index if not exists audit_org_time on audit_events(organization_id,occurred_at desc);
create index if not exists approvals_org_status on approval_requests(organization_id,status,created_at desc);
create index if not exists rules_user on permission_rules(user_id,action);
create index if not exists threads_org on threads(organization_id);
create index if not exists messages_thread on messages(thread_id);
create index if not exists messages_org on messages(organization_id);
create index if not exists messages_user on messages(user_id);
create index if not exists messages_status on messages(status);
